package com.example.planyourtrip.config;
import com.example.planyourtrip.security.rbac.EndpointAuthorizationInterceptor; import org.springframework.context.annotation.Configuration; import org.springframework.web.method.support.HandlerMethodArgumentResolver; import org.springframework.web.servlet.config.annotation.InterceptorRegistry; import org.springframework.web.servlet.config.annotation.WebMvcConfigurer; import java.util.List;
@Configuration public class WebConfig implements WebMvcConfigurer { private final AuthUserResolver resolver; private final EndpointAuthorizationInterceptor endpointAuthorization; public WebConfig(AuthUserResolver resolver, EndpointAuthorizationInterceptor endpointAuthorization){this.resolver=resolver;this.endpointAuthorization=endpointAuthorization;} public void addArgumentResolvers(List<HandlerMethodArgumentResolver> resolvers){resolvers.add(resolver);}
 /** RBAC V1.1 §24 B11 — every partner/admin handler must be in the endpoint authorization registry. */
 public void addInterceptors(InterceptorRegistry registry){registry.addInterceptor(endpointAuthorization);} }
